fun total(price: Int, quantity: Int): Int {
    require(price >= 0 && quantity >= 0) { "Negative value" }
    return Math.multiplyExact(price, quantity)
}
fun main() {
    println(total(12, 3))
    println(total(12, 0))
    try { total(12, -1) }
    catch (error: IllegalArgumentException) { println("Invalid input rejected") }
}

